insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-disney-classics-trivia',
  'Disney Classics Trivia: How Well Do You Know Them?',
  'From Snow White to The Little Mermaid: the films that built the Disney legend. Eight questions on the animated classics everyone grew up with.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Which was Walt Disney''s first full-length animated feature film?","options":[{"id":"a","text":"Pinocchio","is_correct":false},{"id":"b","text":"Snow White and the Seven Dwarfs","is_correct":true},{"id":"c","text":"Fantasia","is_correct":false},{"id":"d","text":"Cinderella","is_correct":false}],"explanation":"It premiered in December 1937 — a huge gamble that paid off and launched Disney''s feature animation era."},{"id":"q2","question":"In which year did Snow White and the Seven Dwarfs premiere?","options":[{"id":"a","text":"1934","is_correct":false},{"id":"b","text":"1940","is_correct":false},{"id":"c","text":"1937","is_correct":true},{"id":"d","text":"1945","is_correct":false}],"explanation":"It premiered on December 21, 1937, at the Carthay Circle Theatre in Los Angeles."},{"id":"q3","question":"In Pinocchio, what is the name of the cricket who acts as the puppet''s conscience?","options":[{"id":"a","text":"Jiminy Cricket","is_correct":true},{"id":"b","text":"Timothy Q. Mouse","is_correct":false},{"id":"c","text":"Archimedes","is_correct":false},{"id":"d","text":"Sebastian","is_correct":false}],"explanation":"Jiminy Cricket sings ''When You Wish Upon a Star''; Timothy Q. Mouse is Dumbo''s friend and Archimedes is Merlin''s owl."},{"id":"q4","question":"What physical feature makes Dumbo the laughingstock of the circus — and later lets him fly?","options":[{"id":"a","text":"His extra-long trunk","is_correct":false},{"id":"b","text":"His pink skin","is_correct":false},{"id":"c","text":"His tiny tail","is_correct":false},{"id":"d","text":"His enormous ears","is_correct":true}],"explanation":"Dumbo''s giant ears become his wings once he stops believing he needs the ''magic feather''."},{"id":"q5","question":"In Cinderella (1950), what does the Fairy Godmother turn into a carriage?","options":[{"id":"a","text":"A pumpkin","is_correct":true},{"id":"b","text":"A watermelon","is_correct":false},{"id":"c","text":"An apple","is_correct":false},{"id":"d","text":"A haystack","is_correct":false}],"explanation":"A pumpkin becomes the carriage while the mice turn into the horses that pull it."},{"id":"q6","question":"Which 1959 film introduced the villain Maleficent?","options":[{"id":"a","text":"Snow White and the Seven Dwarfs","is_correct":false},{"id":"b","text":"Peter Pan","is_correct":false},{"id":"c","text":"Sleeping Beauty","is_correct":true},{"id":"d","text":"Cinderella","is_correct":false}],"explanation":"Maleficent, the ''Mistress of All Evil'', curses baby Aurora at her christening."},{"id":"q7","question":"Which was the last animated feature Walt Disney personally supervised before his death?","options":[{"id":"a","text":"The Aristocats","is_correct":false},{"id":"b","text":"Robin Hood","is_correct":false},{"id":"c","text":"One Hundred and One Dalmatians","is_correct":false},{"id":"d","text":"The Jungle Book","is_correct":true}],"explanation":"Walt died in December 1966; The Jungle Book reached cinemas in October 1967."},{"id":"q8","question":"In One Hundred and One Dalmatians, what does Cruella de Vil want to make out of the puppies?","options":[{"id":"a","text":"A fur coat","is_correct":true},{"id":"b","text":"A fur hat","is_correct":false},{"id":"c","text":"Fur gloves","is_correct":false},{"id":"d","text":"A fur rug","is_correct":false}],"explanation":"Cruella wants a dalmatian-skin coat and hires Horace and Jasper to steal the litter."}]'::jsonb,
  null,
  array['disney', 'animated-classics', 'movies', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-clasicos-disney',
  'Trivia de Disney: ¿cuánto sabes de los clásicos?',
  'De Blancanieves a La sirenita: las películas que construyeron la leyenda Disney. Ocho preguntas sobre los clásicos animados de siempre.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cuál fue el primer largometraje animado de Walt Disney?","options":[{"id":"a","text":"Pinocho","is_correct":false},{"id":"b","text":"Fantasía","is_correct":false},{"id":"c","text":"Blancanieves y los siete enanitos","is_correct":true},{"id":"d","text":"La Cenicienta","is_correct":false}],"explanation":"Se estrenó en diciembre de 1937: una apuesta enorme que dio inicio a la era de los largometrajes animados de Disney."},{"id":"q2","question":"¿En qué año se estrenó Blancanieves y los siete enanitos?","options":[{"id":"a","text":"1937","is_correct":true},{"id":"b","text":"1934","is_correct":false},{"id":"c","text":"1941","is_correct":false},{"id":"d","text":"1945","is_correct":false}],"explanation":"El estreno fue el 21 de diciembre de 1937 en el Carthay Circle Theatre de Los Ángeles."},{"id":"q3","question":"En Pinocho, ¿cómo se llama el grillo que hace de conciencia del muñeco?","options":[{"id":"a","text":"Timoteo","is_correct":false},{"id":"b","text":"Pepito Grillo","is_correct":true},{"id":"c","text":"Arquímides","is_correct":false},{"id":"d","text":"Sebastián","is_correct":false}],"explanation":"Pepito Grillo (Jiminy Cricket) canta ''When You Wish Upon a Star''; Timoteo es el ratón amigo de Dumbo y Arquímides, el búho de Merlín."},{"id":"q4","question":"¿Qué rasgo hace que se burlen de Dumbo en el circo y luego le permite volar?","options":[{"id":"a","text":"Su trompa extra larga","is_correct":false},{"id":"b","text":"Su piel rosada","is_correct":false},{"id":"c","text":"Sus orejas enormes","is_correct":true},{"id":"d","text":"Su cola diminuta","is_correct":false}],"explanation":"Las orejas gigantes de Dumbo se convierten en sus alas cuando deja de creer que necesita la ''pluma mágica''."},{"id":"q5","question":"En La Cenicienta (1950), ¿en qué convierte el Hada Madrina la carroza?","options":[{"id":"a","text":"Una sandía","is_correct":false},{"id":"b","text":"Una manzana","is_correct":false},{"id":"c","text":"Un pajar","is_correct":false},{"id":"d","text":"Una calabaza","is_correct":true}],"explanation":"La calabaza se vuelve carroza y los ratones, los caballos que la tiran."},{"id":"q6","question":"¿Qué película de 1959 presentó a la villana Maléfica?","options":[{"id":"a","text":"La bella durmiente","is_correct":true},{"id":"b","text":"Blancanieves y los siete enanitos","is_correct":false},{"id":"c","text":"Peter Pan","is_correct":false},{"id":"d","text":"La Cenicienta","is_correct":false}],"explanation":"Maléfica, la ''Señora del Mal'', maldice a la bebé Aurora en su bautizo."},{"id":"q7","question":"¿Cuál fue el último largometraje animado que Walt Disney supervisó personalmente?","options":[{"id":"a","text":"Los Aristogatos","is_correct":false},{"id":"b","text":"El libro de la selva","is_correct":true},{"id":"c","text":"Robin Hood","is_correct":false},{"id":"d","text":"101 dálmatas","is_correct":false}],"explanation":"Walt murió en diciembre de 1966; El libro de la selva llegó a los cines en octubre de 1967."},{"id":"q8","question":"En 101 dálmatas, ¿qué quiere fabricar Cruella de Vil con los cachorros?","options":[{"id":"a","text":"Un sombrero de piel","is_correct":false},{"id":"b","text":"Unos guantes de piel","is_correct":false},{"id":"c","text":"Una alfombra de piel","is_correct":false},{"id":"d","text":"Un abrigo de piel","is_correct":true}],"explanation":"Cruella quiere un abrigo de piel de dálmata y contrata a Horacio y Gaspar para robar la camada."}]'::jsonb,
  null,
  array['disney', 'clasicos', 'peliculas', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
