insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-disney-renaissance-trivia',
  'Disney Renaissance Trivia: The 90s Animated Golden Age',
  'The Little Mermaid, The Lion King, Aladdin, Mulan: the decade when Disney animation ruled the world. How well do you know the 90s?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Which film kicked off the Disney Renaissance in 1989?","options":[{"id":"a","text":"Beauty and the Beast","is_correct":false},{"id":"b","text":"The Little Mermaid","is_correct":true},{"id":"c","text":"The Lion King","is_correct":false},{"id":"d","text":"The Rescuers Down Under","is_correct":false}],"explanation":"Ariel''s 1989 debut restarted Disney''s golden age; The Rescuers Down Under arrived a year later."},{"id":"q2","question":"Which Disney film was the first animated movie ever nominated for the Best Picture Oscar?","options":[{"id":"a","text":"The Lion King","is_correct":false},{"id":"b","text":"Aladdin","is_correct":false},{"id":"c","text":"Snow White and the Seven Dwarfs","is_correct":false},{"id":"d","text":"Beauty and the Beast","is_correct":true}],"explanation":"It earned the nomination at the 1992 ceremony, before the Best Animated Feature category existed; it lost to The Silence of the Lambs."},{"id":"q3","question":"Who voiced the Genie in Aladdin (1992)?","options":[{"id":"a","text":"Robin Williams","is_correct":true},{"id":"b","text":"Will Smith","is_correct":false},{"id":"c","text":"Jim Carrey","is_correct":false},{"id":"d","text":"Eddie Murphy","is_correct":false}],"explanation":"Robin Williams improvised much of the role; Will Smith played the Genie only in the 2019 live-action remake."},{"id":"q4","question":"In The Lion King, what is the name of Simba''s father?","options":[{"id":"a","text":"Scar","is_correct":false},{"id":"b","text":"Rafiki","is_correct":false},{"id":"c","text":"Mufasa","is_correct":true},{"id":"d","text":"Zazu","is_correct":false}],"explanation":"Mufasa is the king Scar betrays; Zazu is his hornbill majordomo and Rafiki the wise mandrill."},{"id":"q5","question":"What does the phrase ''Hakuna Matata'' mean?","options":[{"id":"a","text":"No worries","is_correct":true},{"id":"b","text":"Good night","is_correct":false},{"id":"c","text":"Welcome home","is_correct":false},{"id":"d","text":"Follow me","is_correct":false}],"explanation":"It''s a Swahili phrase meaning ''no worries'' — Timon and Pumbaa''s whole life philosophy."},{"id":"q6","question":"Which 1998 film follows a young woman who takes her father''s place in the Chinese army?","options":[{"id":"a","text":"Pocahontas","is_correct":false},{"id":"b","text":"Hercules","is_correct":false},{"id":"c","text":"Tarzan","is_correct":false},{"id":"d","text":"Mulan","is_correct":true}],"explanation":"Mulan disguises herself as a soldier to spare her aging father from conscription."},{"id":"q7","question":"Which pop star wrote and performed the songs in Tarzan (1999)?","options":[{"id":"a","text":"Elton John","is_correct":false},{"id":"b","text":"Phil Collins","is_correct":true},{"id":"c","text":"Sting","is_correct":false},{"id":"d","text":"Bryan Adams","is_correct":false}],"explanation":"Elton John did The Lion King; Phil Collins won an Oscar for ''You''ll Be in My Heart''."},{"id":"q8","question":"In Beauty and the Beast, which enchanted object is Lumière?","options":[{"id":"a","text":"A candelabra","is_correct":true},{"id":"b","text":"A teapot","is_correct":false},{"id":"c","text":"A clock","is_correct":false},{"id":"d","text":"A wardrobe","is_correct":false}],"explanation":"Lumière is the candelabra; Cogsworth is the clock and Mrs. Potts the teapot."}]'::jsonb,
  null,
  array['disney', '90s', 'animation', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
