values (
  'es-trivia-renacimiento-disney',
  'Trivia del Renacimiento de Disney: la era dorada de los 90',
  'La sirenita, El rey león, Aladdín, Mulán: la década en que la animación Disney volvió a dominar el mundo. ¿Cuánto sabes de los 90?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Qué película abrió el Renacimiento de Disney en 1989?","options":[{"id":"a","text":"La bella y la bestia","is_correct":false},{"id":"b","text":"El rey león","is_correct":false},{"id":"c","text":"La sirenita","is_correct":true},{"id":"d","text":"Bernardo y Bianca en Cangurolandia","is_correct":false}],"explanation":"El estreno de Ariel en 1989 reinició la edad de oro; Bernardo y Bianca en Cangurolandia llegó un año después."},{"id":"q2","question":"¿Qué película de Disney fue la primera animada nominada al Óscar a mejor película?","options":[{"id":"a","text":"La bella y la bestia","is_correct":true},{"id":"b","text":"El rey león","is_correct":false},{"id":"c","text":"Aladdín","is_correct":false},{"id":"d","text":"Blancanieves y los siete enanitos","is_correct":false}],"explanation":"Fue nominada en la ceremonia de 1992, antes de que existiera la categoría de mejor película animada; perdió contra El silencio de los inocentes."},{"id":"q3","question":"¿Quién puso la voz al Genio en Aladdín (1992)?","options":[{"id":"a","text":"Will Smith","is_correct":false},{"id":"b","text":"Robin Williams","is_correct":true},{"id":"c","text":"Jim Carrey","is_correct":false},{"id":"d","text":"Eddie Murphy","is_correct":false}],"explanation":"Robin Williams improvisó buena parte del papel; Will Smith fue el Genio solo en el remake de acción real de 2019."},{"id":"q4","question":"En El rey león, ¿cómo se llama el padre de Simba?","options":[{"id":"a","text":"Scar","is_correct":false},{"id":"b","text":"Zazú","is_correct":false},{"id":"c","text":"Rafiki","is_correct":false},{"id":"d","text":"Mufasa","is_correct":true}],"explanation":"Mufasa es el rey al que Scar traiciona; Zazú es su mayordomo bucal y Rafiki el mandril sabio."},{"id":"q5","question":"¿Qué significa la frase ''Hakuna Matata''?","options":[{"id":"a","text":"No te preocupes","is_correct":true},{"id":"b","text":"Buenas noches","is_correct":false},{"id":"c","text":"Bienvenido a casa","is_correct":false},{"id":"d","text":"Sígueme","is_correct":false}],"explanation":"Es una frase en suajili que significa ''sin preocupaciones'': la filosofía de vida de Timón y Pumba."},{"id":"q6","question":"¿Qué película de 1998 sigue a una joven que toma el lugar de su padre en el ejército chino?","options":[{"id":"a","text":"Pocahontas","is_correct":false},{"id":"b","text":"Mulán","is_correct":true},{"id":"c","text":"Hércules","is_correct":false},{"id":"d","text":"Tarzán","is_correct":false}],"explanation":"Mulán se disfraza de soldado para evitar que su anciano padre sea reclutado."},{"id":"q7","question":"¿Qué estrella del pop escribió e interpretó las canciones de Tarzán (1999)?","options":[{"id":"a","text":"Elton John","is_correct":false},{"id":"b","text":"Sting","is_correct":false},{"id":"c","text":"Phil Collins","is_correct":true},{"id":"d","text":"Bryan Adams","is_correct":false}],"explanation":"Elton John hizo El rey león; Phil Collins ganó un Óscar por ''You''ll Be in My Heart''."},{"id":"q8","question":"En La bella y la bestia, ¿qué objeto encantado es Lumière?","options":[{"id":"a","text":"Una tetera","is_correct":false},{"id":"b","text":"Un candelabro","is_correct":true},{"id":"c","text":"Un reloj","is_correct":false},{"id":"d","text":"Un armario","is_correct":false}],"explanation":"Lumière es el candelabro; Din Don es el reloj y la señora Potts, la tetera."}]'::jsonb,
  null,
  array['disney', 'anios-90', 'animacion', 'trivia']::text[],
  3,
  'published',
