insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-pixar-trivia',
  'Pixar Trivia: How Well Do You Know the Movies?',
  'Toy Story, Finding Nemo, Up, Coco and more: eight questions on the studio that changed animation forever. Are you a true Pixar fan?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What was Pixar''s first feature film?","options":[{"id":"a","text":"A Bug''s Life","is_correct":false},{"id":"b","text":"Monsters, Inc.","is_correct":false},{"id":"c","text":"Toy Story","is_correct":true},{"id":"d","text":"Finding Nemo","is_correct":false}],"explanation":"Toy Story (1995) was also the first feature film animated entirely by computer."},{"id":"q2","question":"Who directed Toy Story (1995)?","options":[{"id":"a","text":"Brad Bird","is_correct":false},{"id":"b","text":"John Lasseter","is_correct":true},{"id":"c","text":"Andrew Stanton","is_correct":false},{"id":"d","text":"Pete Docter","is_correct":false}],"explanation":"John Lasseter, Pixar''s creative chief, directed; Stanton and Docter directed later Pixar films."},{"id":"q3","question":"In Finding Nemo, what kind of fish are Marlin and Nemo?","options":[{"id":"a","text":"Clownfish","is_correct":true},{"id":"b","text":"Blue tangs","is_correct":false},{"id":"c","text":"Goldfish","is_correct":false},{"id":"d","text":"Angelfish","is_correct":false}],"explanation":"Marlin and Nemo are clownfish; Dory, their forgetful friend, is the blue tang."},{"id":"q4","question":"Who voices Dory in Finding Nemo?","options":[{"id":"a","text":"Julia Louis-Dreyfus","is_correct":false},{"id":"b","text":"Bonnie Hunt","is_correct":false},{"id":"c","text":"Kristen Wiig","is_correct":false},{"id":"d","text":"Ellen DeGeneres","is_correct":true}],"explanation":"Ellen DeGeneres voices Dory; Albert Brooks plays her anxious companion Marlin."},{"id":"q5","question":"In Up, how does Carl Fredricksen make his house fly?","options":[{"id":"a","text":"Thousands of balloons tied to the house","is_correct":true},{"id":"b","text":"A giant propeller on the roof","is_correct":false},{"id":"c","text":"An airship hidden in the attic","is_correct":false},{"id":"d","text":"A rocket engine in the chimney","is_correct":false}],"explanation":"Carl is a retired balloon salesman — he lifts the house with a sea of helium balloons."},{"id":"q6","question":"In Coco, which Mexican celebration takes Miguel to the Land of the Dead?","options":[{"id":"a","text":"Cinco de Mayo","is_correct":false},{"id":"b","text":"Las Posadas","is_correct":false},{"id":"c","text":"Carnival","is_correct":false},{"id":"d","text":"Día de los Muertos (Day of the Dead)","is_correct":true}],"explanation":"Miguel crosses into the Land of the Dead on Día de los Muertos, when the dead visit the living."},{"id":"q7","question":"What is Buzz Lightyear''s catchphrase?","options":[{"id":"a","text":"''To infinity and beyond!''","is_correct":true},{"id":"b","text":"''Reach for the sky!''","is_correct":false},{"id":"c","text":"''There''s a snake in my boot!''","is_correct":false},{"id":"d","text":"''You are a toy!''","is_correct":false}],"explanation":"''To infinity and beyond!'' is Buzz''s line — the others are Woody''s pull-string phrases."},{"id":"q8","question":"In Monsters, Inc., what do the monsters collect to power their city?","options":[{"id":"a","text":"Children''s laughter","is_correct":false},{"id":"b","text":"Children''s tears","is_correct":false},{"id":"c","text":"Children''s screams","is_correct":true},{"id":"d","text":"Children''s dreams","is_correct":false}],"explanation":"Monstropolis runs on screams — until they learn laughter is far more powerful."}]'::jsonb,
  null,
  array['pixar', 'disney', 'animation', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
