insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-pixar',
  'Trivia de Pixar: ¿cuánto conoces de sus películas?',
  'Toy Story, Buscando a Nemo, Up, Coco y más: ocho preguntas sobre el estudio que cambió la animación para siempre. ¿Eres fan de Pixar?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cuál fue la primera película de Pixar?","options":[{"id":"a","text":"Bichos: una aventura en miniatura","is_correct":false},{"id":"b","text":"Toy Story","is_correct":true},{"id":"c","text":"Monsters, Inc.","is_correct":false},{"id":"d","text":"Buscando a Nemo","is_correct":false}],"explanation":"Toy Story (1995) fue además el primer largometraje animado por completo con computadora."},{"id":"q2","question":"¿Quién dirigió Toy Story (1995)?","options":[{"id":"a","text":"Brad Bird","is_correct":false},{"id":"b","text":"Andrew Stanton","is_correct":false},{"id":"c","text":"John Lasseter","is_correct":true},{"id":"d","text":"Pete Docter","is_correct":false}],"explanation":"La dirigió John Lasseter, jefe creativo de Pixar; Stanton y Docter dirigieron películas posteriores del estudio."},{"id":"q3","question":"En Buscando a Nemo, ¿qué especie de pez son Marlin y Nemo?","options":[{"id":"a","text":"Peces cirujano","is_correct":false},{"id":"b","text":"Peces dorados","is_correct":false},{"id":"c","text":"Peces ángel","is_correct":false},{"id":"d","text":"Peces payaso","is_correct":true}],"explanation":"Marlin y Nemo son peces payaso; Dory, su amiga despistada, es un pez cirujano."},{"id":"q4","question":"¿Quién pone la voz a Dory en la versión original de Buscando a Nemo?","options":[{"id":"a","text":"Ellen DeGeneres","is_correct":true},{"id":"b","text":"Julia Louis-Dreyfus","is_correct":false},{"id":"c","text":"Bonnie Hunt","is_correct":false},{"id":"d","text":"Kristen Wiig","is_correct":false}],"explanation":"Ellen DeGeneres es Dory; Albert Brooks interpreta a Marlin, su acompañante ansioso."},{"id":"q5","question":"En Up, ¿cómo consigue Carl Fredricksen que su casa vuele?","options":[{"id":"a","text":"Con una hélice gigante en el techo","is_correct":false},{"id":"b","text":"Atando miles de globos a la casa","is_correct":true},{"id":"c","text":"Con un dirigible escondido en el ático","is_correct":false},{"id":"d","text":"Con un motor cohete en la chimenea","is_correct":false}],"explanation":"Carl es un vendedor de globos retirado: levanta la casa con un mar de globos de helio."},{"id":"q6","question":"En Coco, ¿qué celebración mexicana lleva a Miguel a la Tierra de los Muertos?","options":[{"id":"a","text":"El Día de Muertos","is_correct":true},{"id":"b","text":"El Cinco de Mayo","is_correct":false},{"id":"c","text":"Las Posadas","is_correct":false},{"id":"d","text":"El Carnaval","is_correct":false}],"explanation":"Miguel cruza a la Tierra de los Muertos en el Día de Muertos, cuando los difuntos visitan a los vivos."},{"id":"q7","question":"¿Cuál es la frase célebre de Buzz Lightyear?","options":[{"id":"a","text":"''¡Alcanza el cielo!''","is_correct":false},{"id":"b","text":"''¡Hay una serpiente en mi bota!''","is_correct":false},{"id":"c","text":"''¡Hasta el infinito y más allá!''","is_correct":true},{"id":"d","text":"''¡Tú eres un juguete!''","is_correct":false}],"explanation":"''¡Hasta el infinito y más allá!'' es la frase de Buzz; las otras son frases de cuerda de Woody."},{"id":"q8","question":"En Monsters, Inc., ¿qué recolectan los monstruos para alimentar Monstrópolis?","options":[{"id":"a","text":"Las risas de los niños","is_correct":false},{"id":"b","text":"Las lágrimas de los niños","is_correct":false},{"id":"c","text":"Los sueños de los niños","is_correct":false},{"id":"d","text":"Los gritos de los niños","is_correct":true}],"explanation":"Monstrópolis funciona con gritos, hasta que descubren que la risa es mucho más poderosa."}]'::jsonb,
  null,
  array['pixar', 'disney', 'animacion', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
