insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-disney-villains-trivia',
  'Disney Villains Trivia: The Bad Guys We Love to Hate',
  'Maleficent, Ursula, Scar, Jafar and the Evil Queen: how much do you know about the villains who made Disney heroes shine?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In Sleeping Beauty, into what does Maleficent transform to fight Prince Phillip?","options":[{"id":"a","text":"A giant snake","is_correct":false},{"id":"b","text":"A dragon","is_correct":true},{"id":"c","text":"A gryphon","is_correct":false},{"id":"d","text":"A storm cloud","is_correct":false}],"explanation":"Maleficent turns into a black dragon — one of the most famous battles in Disney animation."},{"id":"q2","question":"What does Ursula take from Ariel in exchange for human legs?","options":[{"id":"a","text":"Her memories","is_correct":false},{"id":"b","text":"Her pearl necklace","is_correct":false},{"id":"c","text":"Her voice","is_correct":true},{"id":"d","text":"Her father''s trident","is_correct":false}],"explanation":"Ariel trades her voice, which Ursula traps inside the seashell around her neck."},{"id":"q3","question":"Who is Simba''s scheming uncle in The Lion King?","options":[{"id":"a","text":"Mufasa","is_correct":false},{"id":"b","text":"Rafiki","is_correct":false},{"id":"c","text":"Banzai","is_correct":false},{"id":"d","text":"Scar","is_correct":true}],"explanation":"Scar causes Mufasa''s death and convinces Simba it''s his fault; Banzai is one of his hyenas."},{"id":"q4","question":"In One Hundred and One Dalmatians, how many puppies do Pongo and Perdita have?","options":[{"id":"a","text":"15","is_correct":true},{"id":"b","text":"12","is_correct":false},{"id":"c","text":"9","is_correct":false},{"id":"d","text":"101","is_correct":false}],"explanation":"Their litter is fifteen; the famous 101 counts the 84 puppies Cruella kidnapped plus the adults."},{"id":"q5","question":"In Snow White, who does the Evil Queen ask ''who is the fairest of them all''?","options":[{"id":"a","text":"The huntsman","is_correct":false},{"id":"b","text":"Her magic mirror","is_correct":true},{"id":"c","text":"The seven dwarfs","is_correct":false},{"id":"d","text":"Her raven","is_correct":false}],"explanation":"''Mirror, mirror on the wall'' — the mirror''s honest answer is what dooms Snow White."},{"id":"q6","question":"In Peter Pan, which animal stalks Captain Hook hoping for another taste?","options":[{"id":"a","text":"A shark","is_correct":false},{"id":"b","text":"A giant octopus","is_correct":false},{"id":"c","text":"A crocodile","is_correct":true},{"id":"d","text":"A parrot","is_correct":false}],"explanation":"The crocodile swallowed Hook''s hand — and a ticking clock that announces its arrival."},{"id":"q7","question":"In Aladdin, what is Jafar''s job at the Sultan''s court?","options":[{"id":"a","text":"The Sultan''s grand vizier","is_correct":true},{"id":"b","text":"Captain of the palace guards","is_correct":false},{"id":"c","text":"The court sorcerer","is_correct":false},{"id":"d","text":"The royal merchant","is_correct":false}],"explanation":"Jafar is the vizier secretly plotting for the throne; his wisecracking parrot is Iago."},{"id":"q8","question":"Which Disney villain is the god of the Underworld?","options":[{"id":"a","text":"Jafar","is_correct":false},{"id":"b","text":"Ursula","is_correct":false},{"id":"c","text":"Hades","is_correct":true},{"id":"d","text":"Maleficent","is_correct":false}],"explanation":"In Hercules (1997), Hades plans to free the Titans and overthrow Zeus."}]'::jsonb,
  null,
  array['disney', 'villains', 'animation', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
