values (
  'es-trivia-villanos-disney',
  'Trivia de los villanos de Disney: los malos que amamos',
  'Maléfica, Úrsula, Scar, Jafar y la Reina Malvada: ¿cuánto sabes de los villanos que hicieron brillar a los héroes Disney?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"En La bella durmiente, ¿en qué se transforma Maléfica para pelear con el príncipe Felipe?","options":[{"id":"a","text":"En una serpiente gigante","is_correct":false},{"id":"b","text":"En un grifo","is_correct":false},{"id":"c","text":"En un dragón","is_correct":true},{"id":"d","text":"En una nube de tormenta","is_correct":false}],"explanation":"Maléfica se convierte en un dragón negro: una de las batallas más famosas de la animación Disney."},{"id":"q2","question":"¿Qué le quita Úrsula a Ariel a cambio de piernas humanas?","options":[{"id":"a","text":"Sus recuerdos","is_correct":false},{"id":"b","text":"Su voz","is_correct":true},{"id":"c","text":"Su collar de perlas","is_correct":false},{"id":"d","text":"El tridente de su padre","is_correct":false}],"explanation":"Ariel entrega su voz, que Úrsula encierra en el caracol que lleva al cuello."},{"id":"q3","question":"¿Quién es el tío traidor de Simba en El rey león?","options":[{"id":"a","text":"Mufasa","is_correct":false},{"id":"b","text":"Banzai","is_correct":false},{"id":"c","text":"Scar","is_correct":true},{"id":"d","text":"Rafiki","is_correct":false}],"explanation":"Scar provoca la muerte de Mufasa y convence a Simba de que es su culpa; Banzai es una de sus hienas."},{"id":"q4","question":"En 101 dálmatas, ¿cuántos cachorros tienen Pongo y Perdita?","options":[{"id":"a","text":"12","is_correct":false},{"id":"b","text":"9","is_correct":false},{"id":"c","text":"101","is_correct":false},{"id":"d","text":"15","is_correct":true}],"explanation":"Su camada es de quince; los 101 famosos suman los 84 cachorros secuestrados por Cruella más los adultos."},{"id":"q5","question":"En Blancanieves, ¿a quién le pregunta la Reina Malvada quién es la más bella de todas?","options":[{"id":"a","text":"A su espejo mágico","is_correct":true},{"id":"b","text":"Al cazador","is_correct":false},{"id":"c","text":"A los siete enanitos","is_correct":false},{"id":"d","text":"A su cuervo","is_correct":false}],"explanation":"''Espejito, espejito'': la respuesta honesta del espejo es lo que condena a Blancanieves."},{"id":"q6","question":"En Peter Pan, ¿qué animal persigue al Capitán Garfio esperando repetir el bocado?","options":[{"id":"a","text":"Un tiburón","is_correct":false},{"id":"b","text":"Un pulpo gigante","is_correct":false},{"id":"c","text":"Un loro","is_correct":false},{"id":"d","text":"Un cocodrilo","is_correct":true}],"explanation":"El cocodrilo se tragó la mano de Garfio y un reloj que hace tic-tac y delata su llegada."},{"id":"q7","question":"En Aladdín, ¿qué puesto ocupa Jafar en la corte del Sultán?","options":[{"id":"a","text":"Capitán de la guardia del palacio","is_correct":false},{"id":"b","text":"Gran visir del Sultán","is_correct":true},{"id":"c","text":"Hechicero de la corte","is_correct":false},{"id":"d","text":"Mercader real","is_correct":false}],"explanation":"Jafar es el visir que conspira en secreto por el trono; su loro parlanchín es Iago."},{"id":"q8","question":"¿Qué villano de Disney es el dios del Inframundo?","options":[{"id":"a","text":"Jafar","is_correct":false},{"id":"b","text":"Hades","is_correct":true},{"id":"c","text":"Úrsula","is_correct":false},{"id":"d","text":"Maléfica","is_correct":false}],"explanation":"En Hércules (1997), Hades planea liberar a los Titanes para destronar a Zeus."}]'::jsonb,
  null,
  array['disney', 'villanos', 'animacion', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
