insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-disney-songs-trivia',
  'Disney Songs Trivia: The Soundtracks Everyone Knows',
  'From ''When You Wish Upon a Star'' to ''Let It Go'': the Disney songs everyone knows by heart. Can you place each one in its film?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Which Pinocchio song won an Oscar and became Disney''s signature anthem?","options":[{"id":"a","text":"Hi-Diddle-Dee-Dee","is_correct":false},{"id":"b","text":"When You Wish Upon a Star","is_correct":true},{"id":"c","text":"Give a Little Whistle","is_correct":false},{"id":"d","text":"I''ve Got No Strings","is_correct":false}],"explanation":"It won Best Original Song in 1940 and still opens the studio''s logo fanfare."},{"id":"q2","question":"Which Frozen song won the Oscar for Best Original Song?","options":[{"id":"a","text":"Do You Want to Build a Snowman?","is_correct":false},{"id":"b","text":"For the First Time in Forever","is_correct":false},{"id":"c","text":"Love Is an Open Door","is_correct":false},{"id":"d","text":"Let It Go","is_correct":true}],"explanation":"Idina Menzel sang it; Kristen Anderson-Lopez and Robert Lopez wrote it."},{"id":"q3","question":"In which film does Sebastian the crab sing ''Under the Sea''?","options":[{"id":"a","text":"The Little Mermaid","is_correct":true},{"id":"b","text":"Moana","is_correct":false},{"id":"c","text":"Finding Nemo","is_correct":false},{"id":"d","text":"The Princess and the Frog","is_correct":false}],"explanation":"Sebastian''s calypso number won the Oscar for Best Original Song in 1990."},{"id":"q4","question":"Which Aladdin duet won an Oscar and topped the Billboard Hot 100?","options":[{"id":"a","text":"Friend Like Me","is_correct":false},{"id":"b","text":"Prince Ali","is_correct":false},{"id":"c","text":"A Whole New World","is_correct":true},{"id":"d","text":"One Jump Ahead","is_correct":false}],"explanation":"The pop single by Peabo Bryson and Regina Belle reached #1 on the Billboard Hot 100 in 1993."},{"id":"q5","question":"Who wrote and performed ''You''ve Got a Friend in Me'' for Toy Story?","options":[{"id":"a","text":"Elton John","is_correct":false},{"id":"b","text":"Phil Collins","is_correct":false},{"id":"c","text":"Billy Joel","is_correct":false},{"id":"d","text":"Randy Newman","is_correct":true}],"explanation":"Randy Newman''s song opens the film and has been a Pixar staple ever since."},{"id":"q6","question":"Which song opens The Lion King?","options":[{"id":"a","text":"Circle of Life","is_correct":true},{"id":"b","text":"Hakuna Matata","is_correct":false},{"id":"c","text":"Can You Feel the Love Tonight","is_correct":false},{"id":"d","text":"I Just Can''t Wait to Be King","is_correct":false}],"explanation":"The sunrise over the Pride Lands set to ''Circle of Life'' is the film''s first shot."},{"id":"q7","question":"Which Coco song won the Oscar for Best Original Song?","options":[{"id":"a","text":"Un Poco Loco","is_correct":false},{"id":"b","text":"The World Es Mi Familia","is_correct":false},{"id":"c","text":"Proud Corazón","is_correct":false},{"id":"d","text":"Remember Me","is_correct":true}],"explanation":"''Remember Me'' was written by Kristen Anderson-Lopez and Robert Lopez — the same team behind ''Let It Go''."},{"id":"q8","question":"Which Encanto song — about the uncle nobody mentions — became a chart-topping hit?","options":[{"id":"a","text":"Surface Pressure","is_correct":false},{"id":"b","text":"We Don''t Talk About Bruno","is_correct":true},{"id":"c","text":"The Family Madrigal","is_correct":false},{"id":"d","text":"Dos Oruguitas","is_correct":false}],"explanation":"Written by Lin-Manuel Miranda, it reached #1 on the Billboard Hot 100 in 2022."}]'::jsonb,
  null,
  array['disney', 'music', 'soundtracks', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-canciones-disney',
  'Trivia de canciones de Disney: las bandas sonoras de siempre',
  'De «La estrella azul» a «Let It Go»: las canciones Disney que todos saben de memoria. ¿Sabes ubicar cada una en su película?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Qué canción de Pinocho ganó un Óscar y se convirtió en el himno de Disney?","options":[{"id":"a","text":"Hi-Diddle-Dee-Dee","is_correct":false},{"id":"b","text":"Give a Little Whistle","is_correct":false},{"id":"c","text":"When You Wish Upon a Star","is_correct":true},{"id":"d","text":"I''ve Got No Strings","is_correct":false}],"explanation":"Ganó el Óscar a mejor canción original en 1940; en español se conoce como ''La estrella azul'' y aún abre el logo del estudio."},{"id":"q2","question":"¿Qué canción de Frozen ganó el Óscar a mejor canción original?","options":[{"id":"a","text":"Do You Want to Build a Snowman?","is_correct":false},{"id":"b","text":"Let It Go","is_correct":true},{"id":"c","text":"For the First Time in Forever","is_correct":false},{"id":"d","text":"Love Is an Open Door","is_correct":false}],"explanation":"La canta Idina Menzel; en Hispanoamérica se conoce como ''Libre soy'' y la escribieron Kristen Anderson-Lopez y Robert Lopez."},{"id":"q3","question":"¿En qué película canta Sebastián el cangrejo ''Under the Sea'' (Bajo el mar)?","options":[{"id":"a","text":"Moana","is_correct":false},{"id":"b","text":"Buscando a Nemo","is_correct":false},{"id":"c","text":"La princesa y el sapo","is_correct":false},{"id":"d","text":"La sirenita","is_correct":true}],"explanation":"El número calipso de Sebastián ganó el Óscar a mejor canción original en 1990."},{"id":"q4","question":"¿Qué dueto de Aladdín ganó un Óscar y llegó al número 1 del Billboard Hot 100?","options":[{"id":"a","text":"A Whole New World","is_correct":true},{"id":"b","text":"Friend Like Me","is_correct":false},{"id":"c","text":"Prince Ali","is_correct":false},{"id":"d","text":"One Jump Ahead","is_correct":false}],"explanation":"''Un mundo ideal'' en español; la versión pop de Peabo Bryson y Regina Belle llegó al #1 en 1993."},{"id":"q5","question":"¿Quién compuso e interpreta ''You''ve Got a Friend in Me'' (Hay un amigo en mí) de Toy Story?","options":[{"id":"a","text":"Elton John","is_correct":false},{"id":"b","text":"Randy Newman","is_correct":true},{"id":"c","text":"Phil Collins","is_correct":false},{"id":"d","text":"Billy Joel","is_correct":false}],"explanation":"La canción de Randy Newman abre la película y desde entonces es un sello de Pixar."},{"id":"q6","question":"¿Qué canción abre El rey león?","options":[{"id":"a","text":"Hakuna Matata","is_correct":false},{"id":"b","text":"Can You Feel the Love Tonight","is_correct":false},{"id":"c","text":"Circle of Life","is_correct":true},{"id":"d","text":"I Just Can''t Wait to Be King","is_correct":false}],"explanation":"El amanecer sobre las Tierras del Reino con ''Circle of Life'' (El ciclo de la vida) es el primer plano de la película."},{"id":"q7","question":"¿Qué canción de Coco ganó el Óscar a mejor canción original?","options":[{"id":"a","text":"Un Poco Loco","is_correct":false},{"id":"b","text":"Remember Me","is_correct":true},{"id":"c","text":"The World Es Mi Familia","is_correct":false},{"id":"d","text":"Proud Corazón","is_correct":false}],"explanation":"''Recuérdame'' en español; la escribieron Kristen Anderson-Lopez y Robert Lopez, el mismo equipo de ''Let It Go''."},{"id":"q8","question":"¿Qué canción de Encanto —sobre el tío del que nadie habla— se volvió un éxito mundial?","options":[{"id":"a","text":"Surface Pressure","is_correct":false},{"id":"b","text":"The Family Madrigal","is_correct":false},{"id":"c","text":"Dos Oruguitas","is_correct":false},{"id":"d","text":"We Don''t Talk About Bruno","is_correct":true}],"explanation":"''No se habla de Bruno'' en español; la escribió Lin-Manuel Miranda y llegó al #1 del Billboard Hot 100 en 2022."}]'::jsonb,
  null,
  array['disney', 'musica', 'canciones', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

